import XCTest
@testable import GagaEmu

/// .7z import, held to the zip rules. Every archive here is generated by `SevenZipTestArchive`.
final class SevenZipImportTests: XCTestCase {
    private var dir: URL!

    override func setUpWithError() throws {
        dir = FileManager.default.temporaryDirectory.appendingPathComponent("7z-import-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
    }

    override func tearDownWithError() throws {
        try? FileManager.default.removeItem(at: dir)
    }

    private func write(_ name: String, _ data: Data) throws -> URL {
        let url = dir.appendingPathComponent(name)
        try data.write(to: url)
        return url
    }

    private let rom = Data((0..<4096).map { UInt8(truncatingIfNeeded: $0 &* 13) })

    func testOneNDSROMGoesToNDS() throws {
        let archive = SevenZipTestArchive.build([("scan.png", Data("png".utf8)), ("Game/", Data()), ("Game/Game.nds", rom),
                                                 ("Game.nfo", Data("nfo".utf8))])
        XCTAssertEqual(CoreCatalog.platformID(forFile: try write("game.7z", archive)), "nds")
        XCTAssertEqual(CoreCatalog.platformID(forFile: try write("named.zip", archive)), "nds", "a 7z named .zip is read as 7z")

        let url = dir.appendingPathComponent("game.7z")
        let entry = try XCTUnwrap(CoreCatalog.archiveEntries(url).first { $0.name.hasSuffix(".nds") })
        let out = try CoreCatalog.extractZipEntry(entry, from: url, to: dir.appendingPathComponent("Game.nds"),
                                                  limit: CoreCatalog.zipROMLimit("nds"))
        XCTAssertEqual(try Data(contentsOf: out), rom, "decoded past the earlier files in the solid block")
        XCTAssertEqual(try CoreCatalog.extractZipEntry(entry, from: url, to: out, limit: 1 << 30), out, "the same bytes again are the same file")
    }

    func testCopyAndLZMABlocksDecode() throws {
        let copy = try write("copy.7z", SevenZipTestArchive.build([("a.gba", rom)], coder: .copy))
        let copyEntry = try XCTUnwrap(CoreCatalog.archiveEntries(copy).first)
        XCTAssertEqual(try Data(contentsOf: CoreCatalog.extractZipEntry(copyEntry, from: copy, to: dir.appendingPathComponent("a.gba"), limit: 1 << 20)), rom)

        let lzma = try write("lzma.7z", SevenZipTestArchive.build([("b.gba", SevenZipTestArchive.lzmaPayload)], coder: .lzma))
        let lzmaEntry = try XCTUnwrap(CoreCatalog.archiveEntries(lzma).first)
        let out = try CoreCatalog.extractZipEntry(lzmaEntry, from: lzma, to: dir.appendingPathComponent("b.gba"), limit: 1 << 20)
        XCTAssertEqual(try Data(contentsOf: out), SevenZipTestArchive.lzmaPayload)
    }

    func testTwoROMsAsk() throws {
        let url = try write("two.7z", SevenZipTestArchive.build([("a.nds", rom), ("b.gba", rom)]))
        XCTAssertNil(CoreCatalog.platformID(forFile: url))
        XCTAssertEqual(CoreCatalog.unplacedPlatforms(forFile: url)?.map(\.id), ["nds", "gba", "arcade"], "no DOS: DOSBox Pure reads zips only")
        XCTAssertNil(CoreCatalog.platformID(forFile: try write("dos.7z", SevenZipTestArchive.build([("GAME.EXE", rom), ("a.txt", rom)]))))
    }

    func testAMAMESetStaysArcade() throws {
        let text = Data("text".utf8)
        XCTAssertEqual(CoreCatalog.platformID(forFile: try write("set.7z", SevenZipTestArchive.build([("pacman.6e", text), ("82s123", text)]))), "arcade")
        XCTAssertEqual(CoreCatalog.platformID(forFile: try write("gridlee.7z", SevenZipTestArchive.build([("readme.txt", text), ("x.png", text)]))), "arcade",
                       "a MAME machine name")
    }

    func testTraversalOversizeAndBadDataAreRefused() throws {
        XCTAssertNil(CoreCatalog.platformID(forFile: try write("up.7z", SevenZipTestArchive.build([("../evil.nds", rom)]))))
        XCTAssertNil(CoreCatalog.platformID(forFile: try write("abs.7z", SevenZipTestArchive.build([("/tmp/evil.nds", rom)]))))
        // Claims 9 MiB from a few bytes: over the 8 MiB Game Boy limit before anything is decoded.
        let big = try write("big.7z", SevenZipTestArchive.build([("big.gb", rom)], claimedSizes: [9 << 20]))
        XCTAssertNil(CoreCatalog.platformID(forFile: big))
        let entry = try XCTUnwrap(CoreCatalog.archiveEntries(big).first)
        XCTAssertEqual(entry.size, 9 << 20)
        XCTAssertThrowsError(try CoreCatalog.extractZipEntry(entry, from: big, to: dir.appendingPathComponent("big.gb"), limit: CoreCatalog.zipROMLimit("gb"))) {
            XCTAssertEqual($0 as? CoreCatalog.ZipError, .tooLarge)
        }
        // Under the limit it decodes, and a stream shorter than its claim is damaged.
        XCTAssertThrowsError(try CoreCatalog.extractZipEntry(entry, from: big, to: dir.appendingPathComponent("big.gb"), limit: 1 << 30)) {
            XCTAssertEqual($0 as? CoreCatalog.ZipError, .corrupt)
        }

        // A changed data byte fails the CRC-32; a changed header byte fails the header's own CRC.
        var flipped = SevenZipTestArchive.build([("a.nds", rom)], coder: .copy)
        flipped[32 + 100] ^= 0xFF
        let bad = try write("bad.7z", flipped)
        let badEntry = try XCTUnwrap(CoreCatalog.archiveEntries(bad).first)
        XCTAssertThrowsError(try CoreCatalog.extractZipEntry(badEntry, from: bad, to: dir.appendingPathComponent("a.nds"), limit: 1 << 20)) {
            XCTAssertEqual($0 as? CoreCatalog.ZipError, .corrupt)
        }
        var header = SevenZipTestArchive.build([("a.nds", rom)])
        header[header.count - 6] ^= 0xFF
        XCTAssertEqual(CoreCatalog.archiveEntries(try write("header.7z", header)), [])
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: dir.path).filter { $0.hasSuffix(".part") }, [])
    }

    /// Restores the saved library and removes every ROM-folder file a test made.
    @MainActor
    private func cleanUp(_ state: AppState, _ saved: [GameItem], stem: String) {
        state.games = saved
        state.save()
        for name in (try? FileManager.default.contentsOfDirectory(atPath: state.romDirectory.path)) ?? [] where name.hasPrefix(stem) {
            try? FileManager.default.removeItem(at: state.romDirectory.appendingPathComponent(name))
        }
    }

    @MainActor
    func testImportUnpacksARefusesDamageAndRAR() throws {
        let state = AppState()
        let saved = state.games
        let stem = "7z-\(UUID().uuidString)"
        defer { cleanUp(state, saved, stem: stem) }
        try FileManager.default.createDirectory(at: state.romDirectory, withIntermediateDirectories: true)

        let archive = state.romDirectory.appendingPathComponent("\(stem).7z")
        try SevenZipTestArchive.build([("\(stem) (USA).nds", rom), ("cover.png", Data("png".utf8))]).write(to: archive)
        let game = try XCTUnwrap(state.importROM(at: archive))
        XCTAssertEqual(game.platformID, "nds")
        XCTAssertEqual(URL(fileURLWithPath: game.romPath).lastPathComponent, "\(stem) (USA).nds")
        XCTAssertEqual(try Data(contentsOf: URL(fileURLWithPath: game.romPath)), rom)
        XCTAssertFalse(FileManager.default.fileExists(atPath: archive.path), "the copied 7z is not kept")
        try SevenZipTestArchive.build([("\(stem) (USA).nds", rom)]).write(to: archive)
        XCTAssertEqual(state.importROM(at: archive)?.id, game.id, "the same ROM again is the same game")

        var garbled = SevenZipTestArchive.build([("x.nds", rom)])
        garbled[40] ^= 0xFF
        let cases: [(String, String, Data, String)] = [
            ("damaged", "7z", garbled, try XCTUnwrap(CoreCatalog.ZipError.corrupt.errorDescription)),
            ("header", "7z", Data([0x37, 0x7A, 0xBC, 0xAF, 0x27, 0x1C, 0, 4]), try XCTUnwrap(CoreCatalog.ZipError.corrupt.errorDescription)),
            ("up", "7z", SevenZipTestArchive.build([("../evil.nds", rom)]), try XCTUnwrap(CoreCatalog.ZipError.unsafeName.errorDescription)),
            ("rar", "rar", Data("Rar!\u{1A}\u{07}\u{01}\u{00}".utf8) + rom, CoreCatalog.rarMessage),
            ("rar-named-zip", "zip", Data("Rar!\u{1A}\u{07}\u{00}".utf8) + rom, CoreCatalog.rarMessage)
        ]
        for (name, ext, data, note) in cases {
            let url = state.romDirectory.appendingPathComponent("\(stem)-\(name).\(ext)")
            try data.write(to: url)
            XCTAssertNil(state.importROM(at: url), name)
            XCTAssertEqual(state.lastImportNote?.hasSuffix(note), true, name)
            XCTAssertTrue(FileManager.default.fileExists(atPath: url.path), "\(name) stays where it is")
        }
        XCTAssertEqual(state.games.count, saved.count + 1)
    }

    @MainActor
    func testADiscSetUnpacksIntoItsFolder() throws {
        let state = AppState()
        let saved = state.games
        let stem = "7zdisc-\(UUID().uuidString)"
        defer { cleanUp(state, saved, stem: stem) }
        try FileManager.default.createDirectory(at: state.romDirectory, withIntermediateDirectories: true)
        var track = Data(count: 2352 * 20)
        track.replaceSubrange(16..<30, with: Data("SEGADISCSYSTEM".utf8))
        let cue = Data("FILE \"\(stem).bin\" BINARY\n  TRACK 01 MODE1/2352\n    INDEX 01 00:00:00\n".utf8)
        let archive = state.romDirectory.appendingPathComponent("\(stem).7z")
        try SevenZipTestArchive.build([("\(stem).cue", cue), ("\(stem).bin", track)]).write(to: archive)
        let game = try XCTUnwrap(state.importROM(at: archive))
        XCTAssertEqual(game.platformID, "megacd")
        let sheet = URL(fileURLWithPath: game.romPath)
        XCTAssertEqual(sheet.lastPathComponent, "\(stem).cue")
        XCTAssertEqual(sheet.deletingLastPathComponent().lastPathComponent, stem)
        XCTAssertEqual(try Data(contentsOf: sheet.deletingLastPathComponent().appendingPathComponent("\(stem).bin")), track)
        XCTAssertFalse(FileManager.default.fileExists(atPath: archive.path))
    }

    /// Device run 6's three imports, through the function every entry point shares (here as `-GagaImportROM`
    /// does): a PSP 7z named .zip, a PS1 7z disc set with its track first as 7-Zip packs it, and a disksys.rom
    /// whose System copy had been emptied.
    @MainActor
    func testDeviceRunSixImportsThroughTheSharedImport() throws {
        let state = AppState()
        let saved = state.games
        let stem = "7zshared-\(UUID().uuidString)"
        state.systemDirectory = dir.appendingPathComponent("System")
        let romDisksys = state.romDirectory.appendingPathComponent("disksys.rom")
        try XCTSkipIf(FileManager.default.fileExists(atPath: romDisksys.path), "a real disksys.rom is in ROMs")
        defer {
            cleanUp(state, saved, stem: stem)
            try? FileManager.default.removeItem(at: romDisksys)
        }

        var iso = Data(count: 40960)
        iso.replaceSubrange(32776..<32784, with: Data("PSP GAME".utf8))
        let psp = try XCTUnwrap(try state.importDebugROM(at: write("\(stem)-psp.zip", SevenZipTestArchive.build([("\(stem).iso", iso)]))))
        XCTAssertEqual(psp.platformID, "psp")
        XCTAssertEqual(try Data(contentsOf: URL(fileURLWithPath: psp.romPath)), iso)
        XCTAssertFalse(FileManager.default.fileExists(atPath: state.romDirectory.appendingPathComponent("\(stem)-psp.zip").path))
        XCTAssertEqual(state.search, psp.title, "a Debug import puts its game on screen")
        XCTAssertEqual(state.platformFilter, "psp")

        var track = Data(count: 2352 * 20)
        track.replaceSubrange((16 * 2352 + 32)..<(16 * 2352 + 43), with: Data("PLAYSTATION".utf8))
        let cue = Data("FILE \"\(stem).bin\" BINARY\n  TRACK 01 MODE2/2352\n    INDEX 01 00:00:00\n".utf8)
        let ps1 = try XCTUnwrap(try state.importDebugROM(at: write("\(stem)-ps1.7z", SevenZipTestArchive.build([("\(stem).bin", track), ("\(stem).cue", cue)]))))
        XCTAssertEqual(ps1.platformID, "ps1")
        XCTAssertEqual(URL(fileURLWithPath: ps1.romPath).lastPathComponent, "\(stem).cue")

        let system = state.systemDirectory.appendingPathComponent("disksys.rom")
        try FileManager.default.createDirectory(at: state.systemDirectory, withIntermediateDirectories: true)
        try Data().write(to: system)
        let bios = Data(repeating: 0x4C, count: 8 << 10)
        XCTAssertNil(try state.importDebugROM(at: write("disksys.rom", bios)))
        XCTAssertNil(state.lastImportNote)
        XCTAssertEqual(try Data(contentsOf: system), bios, "the emptied System copy is replaced")
        XCTAssertFalse(FileManager.default.fileExists(atPath: romDisksys.path), "not left in ROMs")
        XCTAssertNil(state.launchFailure)
    }

    func testBIOSAndFirmwareNames() {
        XCTAssertEqual(BIOSManagerView.sizes["dsp1.data.rom"], [2048])
        XCTAssertEqual(BIOSManagerView.sizes["dsp1.program.rom"], [6144])
        XCTAssertEqual(BIOSManagerView.sizes["st010.program.rom"], [0xC000])
        XCTAssertEqual(BIOSManagerView.sizes["mpr-17933.bin"], [512 << 10])
    }
}

/// Writes 7z archives for tests: one solid block, no compression beyond what the coder needs.
/// LZMA2 is written as stored chunks; LZMA uses a fixed stream generated with the LZMA SDK's encoder.
enum SevenZipTestArchive {
    enum Coder { case copy, lzma2, lzma }

    /// 64 KiB that the `lzmaStream` fixture decodes to.
    static let lzmaPayload = Data((0..<65536).map { UInt8(truncatingIfNeeded: ($0 &* 7) ^ ($0 >> 14)) })

    /// LzmaEncode output for `lzmaPayload` (dictionary 64 KiB, no end mark): 5 props bytes, then the stream.
    static let lzmaStream = Data(base64Encoded: """
    
    """, options: .ignoreUnknownCharacters)!

    /// `files` in order; a name ending in "/" is a folder. `claimedSizes` replaces the sizes the header records.
    static func build(_ files: [(name: String, data: Data)], coder: Coder = .lzma2, claimedSizes: [Int]? = nil) -> Data {
        let streamed = files.filter { !$0.data.isEmpty }
        let content = streamed.reduce(Data()) { $0 + $1.data }
        let sizes = claimedSizes ?? streamed.map(\.data.count)
        var packed = Data(), coderBytes: [UInt8]
        switch coder {
        case .copy:
            packed = content
            coderBytes = [0x01, 0x00]
        case .lzma2:
            // Stored chunks of up to 64 KiB: control 1 resets the dictionary, 2 keeps it, 0 ends the stream.
            var offset = 0
            while offset < content.count {
                let count = min(65536, content.count - offset)
                packed += [offset == 0 ? 1 : 2, UInt8((count - 1) >> 8), UInt8((count - 1) & 0xFF)]
                packed += content[(content.startIndex + offset)..<(content.startIndex + offset + count)]
                offset += count
            }
            packed.append(0)
            coderBytes = [0x21, 0x21, 0x01, 16]
        case .lzma:
            precondition(content == lzmaPayload, "the LZMA fixture holds only lzmaPayload")
            packed = lzmaStream.dropFirst(5)
            coderBytes = [0x23, 0x03, 0x01, 0x01, 0x05] + lzmaStream.prefix(5)
        }

        var h = Data([0x01])
        if !streamed.isEmpty {
            h += [0x04, 0x06]; number(0, &h); number(1, &h); h.append(0x09); number(packed.count, &h); h.append(0x00)
            h += [0x07, 0x0B]; number(1, &h); h.append(0x00); number(1, &h); h += coderBytes
            h.append(0x0C); number(sizes.reduce(0, +), &h); h.append(0x00)
            h.append(0x08)
            if streamed.count != 1 { h.append(0x0D); number(streamed.count, &h) }
            if streamed.count > 1 { h.append(0x09); sizes.dropLast().forEach { number($0, &h) } }
            h += [0x0A, 0x01]
            for file in streamed { u32(RomPatcher.crc32(file.data), &h) }
            h += [0x00, 0x00]
        }
        h.append(0x05); number(files.count, &h)
        let empty = files.map(\.data.isEmpty)
        if empty.contains(true) {
            let streams = bits(empty)
            h.append(0x0E); number(streams.count, &h); h += streams
            let emptyFiles = bits(files.filter(\.data.isEmpty).map { !$0.name.hasSuffix("/") })
            if files.contains(where: { $0.data.isEmpty && !$0.name.hasSuffix("/") }) {
                h.append(0x0F); number(emptyFiles.count, &h); h += emptyFiles
            }
        }
        var names = Data([0x00])
        for file in files {
            for unit in String(file.name.hasSuffix("/") ? file.name.dropLast() : file.name[...]).utf16 { names += [UInt8(unit & 0xFF), UInt8(unit >> 8)] }
            names += [0, 0]
        }
        h.append(0x11); number(names.count, &h); h += names
        h += [0x00, 0x00]

        var start = Data()
        u64(packed.count, &start); u64(h.count, &start); u32(RomPatcher.crc32(h), &start)
        var out = Data([0x37, 0x7A, 0xBC, 0xAF, 0x27, 0x1C, 0x00, 0x04])
        u32(RomPatcher.crc32(start), &out)
        return out + start + packed + h
    }

    /// 7z's variable-length number: the first byte's leading 1 bits count the little-endian bytes that follow.
    private static func number(_ value: Int, _ data: inout Data) {
        let value = UInt64(value)
        for extra in 0..<8 where value < UInt64(1) << (7 * (extra + 1)) {
            data.append(UInt8(truncatingIfNeeded: (0xFF00 >> extra) & 0xFF) | UInt8(truncatingIfNeeded: value >> (8 * extra)))
            for byte in 0..<extra { data.append(UInt8(truncatingIfNeeded: value >> (8 * byte))) }
            return
        }
        data.append(0xFF)
        for byte in 0..<8 { data.append(UInt8(truncatingIfNeeded: value >> (8 * byte))) }
    }

    private static func bits(_ flags: [Bool]) -> Data {
        var data = Data(count: (flags.count + 7) / 8)
        for (index, flag) in flags.enumerated() where flag { data[index / 8] |= 0x80 >> (index % 8) }
        return data
    }

    private static func u32(_ value: UInt32, _ data: inout Data) { for shift in stride(from: 0, to: 32, by: 8) { data.append(UInt8(truncatingIfNeeded: value >> shift)) } }
    private static func u64(_ value: Int, _ data: inout Data) { for shift in stride(from: 0, to: 64, by: 8) { data.append(UInt8(truncatingIfNeeded: value >> shift)) } }
}
